"""Generate docs/ram_map.md from tools/symbols.py (same source as src/ram.h).

Run after editing symbols.py, together with gen_ram_h.py."""
import os

import symbols

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def cell(s):
    return s.replace('|', '\\|').replace('\n', ' ')


def main():
    defs = sorted(symbols.RAM_DEFS.items())
    n_ver = sum(1 for _, v in defs if v[2] == 'verified')
    out = ['# RAM map',
           '',
           'GENERATED by `tools/gen_ram_map.py` from `tools/symbols.py`. Do not edit: '
           'change `symbols.py`, then rerun this script and `tools/gen_ram_h.py` '
           '(for `src/ram.h`).',
           '',
           'Status: **verified** = re-checked in this project (the note says how: a lifted '
           'routine that passes difftest/lockstep, or a direct observation). **prior** = name '
           'and note imported from the earlier decomp attempt (`battlecity/docs/`), not yet '
           're-verified.',
           '',
           '%d variables: %d verified, %d prior. %d aliases.' % (
               len(defs), n_ver, len(defs) - n_ver, len(symbols.ALIASES)),
           '',
           '| Address | Name | Size | Status | Note |',
           '|---|---|---|---|---|']
    for a, (name, size, status, note) in defs:
        rng = '$%04X' % a if size == 1 else '$%04X-$%04X' % (a, a + size - 1)
        out.append('| `%s` | `%s` | %d | %s | %s |' % (rng, name, size, status, cell(note)))
    out += ['', '## Aliases', '',
            'The same bytes reused for an unrelated purpose. `src/ram.h` defines these '
            'names too.', '',
            '| Address | Name | Size | Note |', '|---|---|---|---|']
    for al in symbols.ALIASES:
        a, name, note = al[:3]
        size = al[3] if len(al) > 3 else 1
        out.append('| `$%04X` | `%s` | %d | %s |' % (a, name, size, cell(note)))
    path = os.path.join(ROOT, 'docs', 'ram_map.md')
    open(path, 'w').write('\n'.join(out) + '\n')
    print('wrote docs/ram_map.md: %d variables, %d aliases' % (len(defs), len(symbols.ALIASES)))


if __name__ == '__main__':
    main()
